import{_ as e,c as i,o as a,a0 as s}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"fr/blog/elite-goal-setting.md","filePath":"fr/blog/elite-goal-setting.md"}');const r=e({name:"fr/blog/elite-goal-setting.md"},[["render",function(e,t,r,o,l,n){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="fixer-des-objectifs-aux-athletes-d-39-elite" tabindex="-1">Fixer des objectifs aux athlètes d&#39;élite <a class="header-anchor" href="#fixer-des-objectifs-aux-athletes-d-39-elite" aria-label="Permalink to &quot;Fixer des objectifs aux athlètes d&amp;#39;élite&quot;">​</a></h1><p>Se fixer des objectifs semble simple : décider de ce que l’on veut et œuvrer pour l’obtenir. Mais la définition d’objectifs de haut niveau est plus nuancée. Les bons objectifs accélèrent le développement ; les mauvais engendrent frustration et stagnation.</p><h2 id="au-dela-des-objectifs-de-base" tabindex="-1">Au-delà des objectifs de base <a class="header-anchor" href="#au-dela-des-objectifs-de-base" aria-label="Permalink to &quot;Au-delà des objectifs de base&quot;">​</a></h2><p>La plupart des joueurs se fixent des objectifs de résultat : « Gagner le championnat régional. » Ces objectifs posent problème :</p><ul><li>Vous ne pouvez pas contrôler entièrement les résultats</li><li>Ils créent une pression sans direction.</li><li>Le succès ou l&#39;échec est binaire.</li><li>Ils ne guident pas la pratique quotidienne</li></ul><p>La définition d&#39;objectifs d&#39;élite va plus loin.</p><h2 id="la-hierarchie-des-objectifs" tabindex="-1">La hiérarchie des objectifs <a class="header-anchor" href="#la-hierarchie-des-objectifs" aria-label="Permalink to &quot;La hiérarchie des objectifs&quot;">​</a></h2><h3 id="niveau-1-objectifs-de-reve-1-a-5-ans" tabindex="-1">Niveau 1 : Objectifs de rêve (1 à 5 ans) <a class="header-anchor" href="#niveau-1-objectifs-de-reve-1-a-5-ans" aria-label="Permalink to &quot;Niveau 1 : Objectifs de rêve (1 à 5 ans)&quot;">​</a></h3><p>Vos aspirations ultimes :</p><ul><li>« Participer à la compétition nationale »</li><li>« Être reconnu comme un tireur d&#39;élite »</li><li>« Gagner un championnat majeur »</li></ul><p>Elles fournissent une orientation et une motivation, mais ne sont pas applicables au quotidien.</p><h3 id="niveau-2-objectifs-de-performance-saison-annee" tabindex="-1">Niveau 2 : Objectifs de performance (Saison/Année) <a class="header-anchor" href="#niveau-2-objectifs-de-performance-saison-annee" aria-label="Permalink to &quot;Niveau 2 : Objectifs de performance (Saison/Année)&quot;">​</a></h3><p>Améliorations mesurables dans votre jeu :</p><ul><li>« Augmenter la précision de tir de 60 % à 70 % »</li><li>« Réduire les erreurs non provoquées de 25 % »</li><li>&quot;Développez une plombée fiable&quot;</li></ul><p>Ces éléments sont sous votre contrôle et mesurables.</p><h3 id="niveau-3-objectifs-de-processus-quotidiens-hebdomadaires" tabindex="-1">Niveau 3 : Objectifs de processus (quotidiens/hebdomadaires) <a class="header-anchor" href="#niveau-3-objectifs-de-processus-quotidiens-hebdomadaires" aria-label="Permalink to &quot;Niveau 3 : Objectifs de processus (quotidiens/hebdomadaires)&quot;">​</a></h3><p>Les actions qui favorisent l&#39;amélioration :</p><ul><li>&quot;Routine complète de préparation avant chaque lancer&quot;</li><li>&quot;Pratiquez la visualisation pendant 10 minutes par jour&quot;</li><li>&quot;Entraînez-vous à la technique de tir 3 fois par semaine&quot;</li></ul><p>Ces éléments sont entièrement contrôlables et contribuent à l&#39;atteinte des objectifs de performance.</p><h2 id="le-cadre-smart" tabindex="-1">Le cadre SMART+ <a class="header-anchor" href="#le-cadre-smart" aria-label="Permalink to &quot;Le cadre SMART+&quot;">​</a></h2><p>Allez au-delà des objectifs SMART de base :</p><h3 id="specifique" tabindex="-1">Spécifique <a class="header-anchor" href="#specifique" aria-label="Permalink to &quot;Spécifique&quot;">​</a></h3><p>Non pas « améliorer mon pointage », mais « développer une demi-portée régulière qui atterrisse à moins de 30 cm de la cible à 8 mètres ».</p><h3 id="mesurable" tabindex="-1">Mesurable <a class="header-anchor" href="#mesurable" aria-label="Permalink to &quot;Mesurable&quot;">​</a></h3><p>Définissez comment vous suivrez les progrès :</p><ul><li>Pourcentages de réussite</li><li>Mesures de cohérence</li><li>marqueurs d&#39;analyse vidéo</li></ul><h3 id="realisable-mais-ambitieux" tabindex="-1">Réalisable mais ambitieux <a class="header-anchor" href="#realisable-mais-ambitieux" aria-label="Permalink to &quot;Réalisable mais ambitieux&quot;">​</a></h3><p>L&#39;objectif doit encourager la progression tout en restant réaliste. Un tireur à 60 % qui vise 65 % a un objectif atteignable ; viser 90 % relève de l&#39;utopie.</p><h3 id="pertinent" tabindex="-1">Pertinent <a class="header-anchor" href="#pertinent" aria-label="Permalink to &quot;Pertinent&quot;">​</a></h3><p>Les objectifs doivent être en lien avec vos aspirations plus larges et s&#39;attaquer aux faiblesses réelles, et non pas seulement à ce qui est facile à améliorer.</p><h3 id="limite-dans-le-temps" tabindex="-1">Limité dans le temps <a class="header-anchor" href="#limite-dans-le-temps" aria-label="Permalink to &quot;Limité dans le temps&quot;">​</a></h3><p>Fixez des échéances claires :</p><ul><li>&quot;D&#39;ici la fin de la saison&quot;</li><li>«Dans les 3 mois»</li><li>&quot;Par le championnat national&quot;</li></ul><h3 id="personnellement-significatif" tabindex="-1">+ Personnellement significatif <a class="header-anchor" href="#personnellement-significatif" aria-label="Permalink to &quot;+ Personnellement significatif&quot;">​</a></h3><p>Cet objectif doit avoir de l&#39;importance pour VOUS, et pas seulement pour votre entraîneur ou vos coéquipiers. La motivation intrinsèque permet de maintenir l&#39;effort même lorsque les progrès sont lents.</p><h2 id="processus-vs-resultat" tabindex="-1">Processus vs. résultat <a class="header-anchor" href="#processus-vs-resultat" aria-label="Permalink to &quot;Processus vs. résultat&quot;">​</a></h2><h3 id="le-probleme-des-objectifs-de-resultats" tabindex="-1">Le problème des objectifs de résultats <a class="header-anchor" href="#le-probleme-des-objectifs-de-resultats" aria-label="Permalink to &quot;Le problème des objectifs de résultats&quot;">​</a></h3><p>« Gagner le match » pose problème :</p><ul><li>L&#39;anxiété liée à des choses que vous ne pouvez pas contrôler</li><li>Distraction par rapport à l&#39;exécution</li><li>Pensée du tout ou rien</li><li>Pression sans conseils</li></ul><h3 id="le-pouvoir-des-objectifs-de-processus" tabindex="-1">Le pouvoir des objectifs de processus <a class="header-anchor" href="#le-pouvoir-des-objectifs-de-processus" aria-label="Permalink to &quot;Le pouvoir des objectifs de processus&quot;">​</a></h3><p>« Exécuter parfaitement ma routine de préparation à la prise de vue » propose :</p><ul><li>Contrôle total</li><li>Concentration claire</li><li>Réponse immédiate</li><li>Construit naturellement vers des résultats.</li></ul><h3 id="l-39-equilibre" tabindex="-1">L&#39;équilibre <a class="header-anchor" href="#l-39-equilibre" aria-label="Permalink to &quot;L&amp;#39;équilibre&quot;">​</a></h3><p>Utilisez les objectifs de résultat pour la motivation et l&#39;orientation. Utilisez les objectifs de processus pour la concentration et l&#39;exécution au quotidien.</p><h2 id="definition-des-objectifs-pour-les-differentes-phases" tabindex="-1">Définition des objectifs pour les différentes phases <a class="header-anchor" href="#definition-des-objectifs-pour-les-differentes-phases" aria-label="Permalink to &quot;Définition des objectifs pour les différentes phases&quot;">​</a></h2><h3 id="hors-saison" tabindex="-1">Hors saison <a class="header-anchor" href="#hors-saison" aria-label="Permalink to &quot;Hors saison&quot;">​</a></h3><p>Mettre l&#39;accent sur les objectifs de développement :</p><ul><li>Améliorations techniques</li><li>Conditionnement physique</li><li>Développement des compétences mentales</li><li>Élargir votre palette de jetés</li></ul><h3 id="pre-saison" tabindex="-1">Pré-saison <a class="header-anchor" href="#pre-saison" aria-label="Permalink to &quot;Pré-saison&quot;">​</a></h3><p>Transition vers l&#39;intégration :</p><ul><li>Combiner les compétences dans des conditions similaires à celles d&#39;un match</li><li>Améliorations testées en compétition amicale</li><li>Stratégies d&#39;amélioration</li></ul><h3 id="saison-de-competition" tabindex="-1">Saison de compétition <a class="header-anchor" href="#saison-de-competition" aria-label="Permalink to &quot;Saison de compétition&quot;">​</a></h3><p>Passer à la performance et aux processus :</p><ul><li>Mettre en œuvre ce que vous avez développé</li><li>Objectifs de processus pour chaque match</li><li>Modifications techniques minimales</li></ul><h3 id="apres-la-competition" tabindex="-1">Après la compétition <a class="header-anchor" href="#apres-la-competition" aria-label="Permalink to &quot;Après la compétition&quot;">​</a></h3><p>Réflexion et planification :</p><ul><li>Analysez ce qui a fonctionné</li><li>Identifier les axes de croissance</li><li>Fixez-vous des objectifs pour le prochain cycle.</li></ul><h2 id="erreurs-courantes-lors-de-la-definition-d-39-objectifs" tabindex="-1">Erreurs courantes lors de la définition d&#39;objectifs <a class="header-anchor" href="#erreurs-courantes-lors-de-la-definition-d-39-objectifs" aria-label="Permalink to &quot;Erreurs courantes lors de la définition d&amp;#39;objectifs&quot;">​</a></h2><h3 id="trop-d-39-objectifs" tabindex="-1">Trop d&#39;objectifs <a class="header-anchor" href="#trop-d-39-objectifs" aria-label="Permalink to &quot;Trop d&amp;#39;objectifs&quot;">​</a></h3><p>La concentration est la clé du succès. 2 ou 3 objectifs clés valent mieux que 10 objectifs dispersés.</p><h3 id="objectifs-de-resultats-uniquement" tabindex="-1">Objectifs de résultats uniquement <a class="header-anchor" href="#objectifs-de-resultats-uniquement" aria-label="Permalink to &quot;Objectifs de résultats uniquement&quot;">​</a></h3><p>Sans objectifs de processus, vous n&#39;avez pas de feuille de route.</p><h3 id="aucune-flexibilite" tabindex="-1">Aucune flexibilité <a class="header-anchor" href="#aucune-flexibilite" aria-label="Permalink to &quot;Aucune flexibilité&quot;">​</a></h3><p>Les objectifs doivent s&#39;adapter aux nouvelles informations. S&#39;en tenir rigidement à des objectifs obsolètes est une perte de temps.</p><h3 id="objectifs-fondes-sur-la-comparaison" tabindex="-1">Objectifs fondés sur la comparaison <a class="header-anchor" href="#objectifs-fondes-sur-la-comparaison" aria-label="Permalink to &quot;Objectifs fondés sur la comparaison&quot;">​</a></h3><p>« Être meilleur que [joueur] » revient à confier son succès à quelqu&#39;un d&#39;autre.</p><h3 id="negliger-les-objectifs-mentaux" tabindex="-1">Négliger les objectifs mentaux <a class="header-anchor" href="#negliger-les-objectifs-mentaux" aria-label="Permalink to &quot;Négliger les objectifs mentaux&quot;">​</a></h3><p>Les objectifs techniques et physiques prédominent, mais les aptitudes mentales déterminent souvent le vainqueur.</p><h2 id="strategies-de-mise-en-œuvre" tabindex="-1">Stratégies de mise en œuvre <a class="header-anchor" href="#strategies-de-mise-en-œuvre" aria-label="Permalink to &quot;Stratégies de mise en œuvre&quot;">​</a></h2><h3 id="notez-les" tabindex="-1">Notez-les <a class="header-anchor" href="#notez-les" aria-label="Permalink to &quot;Notez-les&quot;">​</a></h3><p>Les objectifs écrits ont beaucoup plus de chances d&#39;être atteints.</p><h3 id="examiner-regulierement" tabindex="-1">Examiner régulièrement <a class="header-anchor" href="#examiner-regulierement" aria-label="Permalink to &quot;Examiner régulièrement&quot;">​</a></h3><p>Un bilan hebdomadaire permet de garder les objectifs en tête et de les ajuster.</p><h3 id="partager-de-maniere-selective" tabindex="-1">Partager de manière sélective <a class="header-anchor" href="#partager-de-maniere-selective" aria-label="Permalink to &quot;Partager de manière sélective&quot;">​</a></h3><p>Partagez avec ceux qui vous soutiendront, et non ceux qui vous discréditeront.</p><h3 id="visualiser-la-reussite" tabindex="-1">Visualiser la réussite <a class="header-anchor" href="#visualiser-la-reussite" aria-label="Permalink to &quot;Visualiser la réussite&quot;">​</a></h3><p>Visualisez régulièrement la réalisation de vos objectifs — la sensation, le moment.</p><h3 id="suivre-les-progres" tabindex="-1">Suivre les progrès <a class="header-anchor" href="#suivre-les-progres" aria-label="Permalink to &quot;Suivre les progrès&quot;">​</a></h3><p>Ce qui se mesure se gère. Conservez des traces.</p><h2 id="lorsque-les-objectifs-ne-sont-pas-atteints" tabindex="-1">Lorsque les objectifs ne sont pas atteints <a class="header-anchor" href="#lorsque-les-objectifs-ne-sont-pas-atteints" aria-label="Permalink to &quot;Lorsque les objectifs ne sont pas atteints&quot;">​</a></h2><p>Les objectifs non atteints ne sont pas des échecs, ce sont des données :</p><ol><li><strong>Analyse</strong> : Pourquoi cet objectif n’a-t-il pas été atteint ?</li><li><strong>Apprenez</strong> : Qu’est-ce que cela vous apprend ?</li><li><strong>Ajuster</strong> : Modifier l’objectif ou l’approche</li><li><strong>À suivre</strong> : La persévérance l&#39;emporte sur la perfection</li></ol><h2 id="le-jeu-mental-des-objectifs" tabindex="-1">Le jeu mental des objectifs <a class="header-anchor" href="#le-jeu-mental-des-objectifs" aria-label="Permalink to &quot;Le jeu mental des objectifs&quot;">​</a></h2><p>Les objectifs influencent la psychologie :</p><ul><li><strong>Trop facile</strong> : Ennui, complaisance</li><li><strong>Trop difficile</strong> : Anxiété, découragement</li><li><strong>Parfait</strong> : Engagement, fluidité, croissance</li></ul><p>Trouvez le juste milieu où les objectifs sont stimulants sans être insurmontables.</p><hr><p>| <em>À consulter également : <a href="/en/education/goals/">Introduction à la définition d’objectifs</a> | <a href="/en/education/goals/smart-goals">Objectifs SMART</a> | <a href="/en/education/goals/planning">Planifier votre développement</a></em> |</p>',88)])])}]]);export{t as __pageData,r as default};
